PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64
.visible .entry triu_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    .reg .pred %p<20>;
    .reg .s32  %r<60>;
    .reg .s64  %rd<20>;
    .reg .f32  %f<20>;
    .shared .align 4 .f32 smA[272];
    .shared .align 4 .f32 smB[272];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1,  [N];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r2, %tid.x;      // tx
    mov.u32 %r3, %tid.y;      // ty
    mov.u32 %r4, %ctaid.x;    // bx
    mov.u32 %r5, %ctaid.y;    // by
    mul.lo.s32 %r6, %r4, 16;  // colBase
    mul.lo.s32 %r7, %r5, 16;  // rowBase
    add.s32 %r8, %r6, %r2;    // col
    add.s32 %r9, %r7, %r3;    // row
    setp.ge.s32 %p1, %r8, %r1;   // col>=N
    setp.ge.s32 %p2, %r9, %r1;   // row>=N
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;
    // address of C[row][col]
    mul.lo.s32 %r10, %r9, %r1;
    add.s32 %r11, %r10, %r8;
    mul.wide.s32 %rd4, %r11, 4;
    add.s64 %rd5, %rd3, %rd4;   // &C[row][col]
    setp.gt.s32 %p4, %r5, %r4;  // by > bx -> block fully below diagonal
    @%p4 bra STORE_ZERO;
    // k-tile loop bounds: kt from by to bx inclusive
    mov.s32 %r12, %r5;    // kt = by
    mov.f32 %f1, 0f00000000;   // accumulator
KT_LOOP:
    setp.gt.s32 %p5, %r12, %r4;   // kt > bx -> done
    @%p5 bra STORE_SUM;
    mul.lo.s32 %r13, %r12, 16;    // kBase
    // ---- load A tile element: A[row][kBase+tx] ----
    add.s32 %r14, %r13, %r2;      // aCol = kBase+tx
    setp.lt.s32 %p6, %r14, %r1;   // aCol<N
    mov.f32 %f2, 0f00000000;
    @!%p6 bra A_LOAD_DONE;
    mul.lo.s32 %r15, %r9, %r1;    // row*N
    add.s32 %r16, %r15, %r14;
    mul.wide.s32 %rd6, %r16, 4;
    add.s64 %rd7, %rd1, %rd6;
    ld.global.f32 %f2, [%rd7];
A_LOAD_DONE:
    mad.lo.s32 %r17, %r3, 17, %r2;   // ty*17+tx
    mul.lo.s32 %r18, %r17, 4;
    mov.u32 %r19, smA;
    add.s32 %r20, %r19, %r18;
    st.shared.f32 [%r20], %f2;
    // ---- load B tile element: B[kBase+ty][col] ----
    add.s32 %r21, %r13, %r3;      // bRow = kBase+ty
    setp.lt.s32 %p7, %r21, %r1;   // bRow<N
    mov.f32 %f3, 0f00000000;
    @!%p7 bra B_LOAD_DONE;
    mul.lo.s32 %r22, %r21, %r1;   // bRow*N
    add.s32 %r23, %r22, %r8;      // + col
    mul.wide.s32 %rd8, %r23, 4;
    add.s64 %rd9, %rd2, %rd8;
    ld.global.f32 %f3, [%rd9];
B_LOAD_DONE:
    mad.lo.s32 %r24, %r3, 17, %r2;   // ty*17+tx
    mul.lo.s32 %r25, %r24, 4;
    mov.u32 %r26, smB;
    add.s32 %r27, %r26, %r25;
    st.shared.f32 [%r27], %f3;
    bar.sync 0;
    // compute partial sum over 16 k values
    mov.s32 %r28, 0;               // kk
    mad.lo.s32 %r29, %r3, 17, 0;   // base offset for smA row (ty*17)
    mov.s32 %r30, %r2;             // tx (col local index for smB)
COMPUTE_LOOP:
    setp.ge.s32 %p8, %r28, 16;
    @%p8 bra COMPUTE_DONE;
    add.s32 %r31, %r29, %r28;      // smA index = ty*17+kk
    mul.lo.s32 %r32, %r31, 4;
    mov.u32 %r33, smA;
    add.s32 %r34, %r33, %r32;
    ld.shared.f32 %f4, [%r34];
    mad.lo.s32 %r35, %r28, 17, %r30;  // smB index = kk*17+tx
    mul.lo.s32 %r36, %r35, 4;
    mov.u32 %r37, smB;
    add.s32 %r38, %r37, %r36;
    ld.shared.f32 %f5, [%r38];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    add.s32 %r28, %r28, 1;
    bra.uni COMPUTE_LOOP;
COMPUTE_DONE:
    bar.sync 0;
    add.s32 %r12, %r12, 1;   // kt++
    bra.uni KT_LOOP;
STORE_SUM:
    st.global.f32 [%rd5], %f1;
    bra.uni DONE;
STORE_ZERO:
    mov.f32 %f6, 0f00000000;
    st.global.f32 [%rd5], %f6;
DONE:
    ret;
