        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"
        assert A.shape == B.shape and A.dim() == 2 and A.shape[0] == A.shape[1], "Square matrices required"

        A = A.contiguous()
        B = B.contiguous()

        N = A.shape[0]

        C = torch.empty((N, N), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block_x, block_y = 16, 16
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y

        module.launch(
            "triu_matmul",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C
